#!/bin/bash
# Rebuilds ../plantuml.js from a PlantUML source checkout. See extensions/prism/README.md, "PlantUML engine".
# Usage: build.sh <plantuml-checkout>
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
checkout=$(cd "${1:?usage: build.sh <plantuml-checkout>}" && pwd)
out="$here/../plantuml.js"

# npmPackage stamps the real version into the engine, where generateJavaScript leaves "$version$".
(cd "$checkout" && ./gradlew :plantuml-mcp-js:npmPackage -Pfast)

stage=$(mktemp -d)
trap 'rm -rf "$stage"' EXIT
cp "$here/worker.js" "$here/package.json" "$here/package-lock.json" "$stage/"
cp "$checkout/plantuml-mcp-js/build/npm-mcp-js/engine.js" "$stage/engine.js"
cp "$checkout/src/main/teavm/generated/themes.js" "$stage/themes.js"
(cd "$stage" && npm ci --no-audit --no-fund)

commit=$(git -C "$checkout" rev-parse HEAD)
version=$(cd "$stage" && node -e 'import("./engine.js").then(m => console.log(m.version()))')
(cd "$stage" && npx esbuild worker.js --bundle --platform=node --format=esm --minify --loader:.wasm=binary \
  --banner:js="// Generated by extensions/prism/core/vendor/plantuml/build.sh from $version, commit $commit. Do not edit." \
  --outfile="$out")

echo "plantuml.js: $(du -h "$out" | cut -f1), $version, commit $commit"
